/**
 * Video quality policy + adaptive step-down/step-up. Pure (no React, no native modules) so it is unit-testable.
 *
 * Exercise demos are ~10 s looping clips, so the app uses small H.264 MP4 renditions (240/360/540) generated by the
 * backend instead of the 8-10 MB HEVC original. Quality is chosen from:
 *   1. the user's Data Saver mode and manual quality choice,
 *   2. the connection type (Wi-Fi / cellular), and
 *   3. what actually happens during playback (stalls) — never only Wi-Fi vs cellular.
 */
export type VideoTier = '240' | '360' | '540';
export type VideoPref = 'auto' | VideoTier;
export type DataSaverMode = 'auto' | 'saver' | 'high';
export type NetworkKind = 'wifi' | 'cellular' | 'none' | 'unknown';

export const TIERS: VideoTier[] = ['240', '360', '540'];
const rank = (t: VideoTier) => TIERS.indexOf(t);
export const minTier = (a: VideoTier, b: VideoTier): VideoTier => (rank(a) <= rank(b) ? a : b);

export interface VideoVariantInfo {
  quality: string;
  url: string;
  bytes?: number;
  bitrateKbps?: number;
}

export interface MediaPolicyInput {
  mode: DataSaverMode;
  network: NetworkKind;
  videoPref: VideoPref;
  /** Highest tier the connection has proven it can sustain this session (set by the stall tracker). */
  ceiling?: VideoTier | null;
}

export interface MediaPolicy {
  /** Data Saver is effectively on (user choice, or automatic on cellular). */
  saver: boolean;
  /** Highest rendition the player may use right now. */
  tier: VideoTier;
  /** Videos outside the active workout reel (cards, Home) may start by themselves. Otherwise: poster + tap to play. */
  autoplayOutsideWorkout: boolean;
  /** True when a manual quality above what Data Saver would pick is selected (UI shows a data warning). */
  manualHighWarning: boolean;
}

export function resolveMediaPolicy({ mode, network, videoPref, ceiling }: MediaPolicyInput): MediaPolicy {
  const saver = mode === 'saver' || (mode === 'auto' && network === 'cellular');

  // Baseline tier for "Auto"
  let tier: VideoTier;
  if (mode === 'high') tier = network === 'cellular' ? '540' : '540';
  else if (saver) tier = '360';
  else tier = network === 'wifi' ? '540' : '360';

  const autoTier = tier;
  if (videoPref !== 'auto') tier = videoPref; // explicit choice wins over the baseline
  // Observed playback problems always lower the tier, even over a manual choice, so videos keep working.
  if (ceiling) tier = minTier(tier, ceiling);
  // Offline / unknown-and-saver: be conservative.
  if (network === 'none') tier = '240';

  return {
    saver,
    tier,
    autoplayOutsideWorkout: !saver && network === 'wifi',
    manualHighWarning: videoPref !== 'auto' && rank(videoPref) > rank(saver ? '360' : autoTier) && (saver || network === 'cellular'),
  };
}

/** Largest rendition <= tier; if none is that small, the smallest available. */
export function pickVariant<T extends VideoVariantInfo>(variants: T[] | null | undefined, tier: VideoTier): T | null {
  if (!variants?.length) return null;
  const sorted = [...variants].filter((v) => TIERS.includes(v.quality as VideoTier)).sort((a, b) => rank(a.quality as VideoTier) - rank(b.quality as VideoTier));
  if (!sorted.length) return null;
  const fit = sorted.filter((v) => rank(v.quality as VideoTier) <= rank(tier));
  return fit.length ? fit[fit.length - 1] : sorted[0];
}

export interface VideoSourceDescriptor {
  uri: string;
  quality: VideoTier | 'original';
  kind: 'mp4' | 'hls' | 'original';
}

/**
 * Which URL to play. Short clips use the progressive MP4 rendition (one request, cacheable on iOS AND Android,
 * seamless loop). HLS is only for LONG videos where adaptive segments pay off, and it is not cacheable on iOS.
 * Falls back to the original file when no optimised rendition exists yet (e.g. just uploaded).
 */
export function pickVideoSource(
  video: { url?: string | null; variants?: VideoVariantInfo[] | null; hlsUrl?: string | null; durationSec?: number | null },
  tier: VideoTier,
  resolve: (u: string | null | undefined) => string | null | undefined = (u) => u
): VideoSourceDescriptor | null {
  const isLong = (video.durationSec ?? 0) > 45;
  if (isLong && video.hlsUrl) {
    const hls = resolve(video.hlsUrl);
    if (hls) return { uri: hls, quality: tier, kind: 'hls' };
  }
  const v = pickVariant(video.variants, tier);
  if (v) {
    const uri = resolve(v.url);
    if (uri) return { uri, quality: v.quality as VideoTier, kind: 'mp4' };
  }
  const original = resolve(video.url);
  return original ? { uri: original, quality: 'original', kind: 'original' } : null;
}

// ───────────────────────────── adaptive stall tracking ─────────────────────────────

export interface StallState {
  /** Current ceiling (null = nothing observed yet). */
  ceiling: VideoTier | null;
  stallTimes: number[];
  smoothLoops: number;
}

export const initialStallState = (): StallState => ({ ceiling: null, stallTimes: [], smoothLoops: 0 });

const STALL_WINDOW_MS = 25_000;
/** A single rebuffer this long, or this many within the window, means the current rendition is too heavy. */
export const LONG_STALL_MS = 3_000;
export const STALLS_BEFORE_STEP_DOWN = 2;
export const SMOOTH_LOOPS_BEFORE_STEP_UP = 3;

/** Record a rebuffering event. Returns the new state and whether the tier must step down. */
export function onStall(state: StallState, currentTier: VideoTier, durationMs: number, now: number): { state: StallState; stepDown: boolean } {
  const recent = [...state.stallTimes.filter((t) => now - t < STALL_WINDOW_MS), now];
  const heavy = durationMs >= LONG_STALL_MS || recent.length >= STALLS_BEFORE_STEP_DOWN;
  if (!heavy || rank(currentTier) === 0) return { state: { ...state, stallTimes: recent, smoothLoops: 0 }, stepDown: false };
  const lower = TIERS[rank(currentTier) - 1];
  return { state: { ceiling: lower, stallTimes: [], smoothLoops: 0 }, stepDown: true };
}

/** A full loop without rebuffering. After a few, the ceiling is raised one step (never above `policyTier`). */
export function onSmoothLoop(state: StallState, policyTier: VideoTier): { state: StallState; stepUp: boolean } {
  if (!state.ceiling) return { state, stepUp: false };
  const loops = state.smoothLoops + 1;
  if (loops < SMOOTH_LOOPS_BEFORE_STEP_UP) return { state: { ...state, smoothLoops: loops }, stepUp: false };
  const higher = TIERS[Math.min(rank(state.ceiling) + 1, TIERS.length - 1)];
  const reached = rank(higher) >= rank(policyTier);
  return { state: { ceiling: reached ? null : higher, stallTimes: [], smoothLoops: 0 }, stepUp: true };
}

/** Rough "can this link play a rendition?" check: needs average kbps below ~80% of the measured throughput. */
export function sustainable(bitrateKbps: number, measuredKbps: number): boolean {
  return measuredKbps <= 0 ? true : bitrateKbps <= measuredKbps * 0.8;
}
